                  "      markerFormat: function(parm) {\r",
                  "        let rtn = {};\r",
                  '        rtn.show = false;\r',
                  '        if ( parm.id=="2015" ) {\r',
                  '          rtn.show = true;\r',
                  '          rtn.type = "wye";  // cross, diamond, wye, star\r',
                  "          rtn.radius = 20;\r",
                  "          if ( parm.index==3 ) {\r",
