                      "      mapMarker : {\r",
                      "        show: true,\r",
                      "        useLatLon: true,\r",
                      '        defaultValue: { radius:10, labelColor:"red", fontSize:26, fontWeight:"bold"},\r',
                      "        jsonMarker: [\r",
                      '          {"id":"mkr-001",     "type": "circle","useLatLon":"false", "position": [ {"x":100,"y":200}], "label":"충북", "fillColor":"#00FFAB", "fillOpacity":"0.2"},\r',
                      '          {"id":"mkr-img-001", "type": "image", "imageUrl":"./images/map-pin1.png", "position": [ {"x":126.9152195932067,"y":37.440055999842087}], \'label\':"출발", "fontSize":20},\r',
                      '          {"id":"mkr-line-001","type": "line",  "strokeColor":"blue", "strokeOpacity":"1", "strokeWidth":"5", "strokeStyle":"dashed","useArrow":"true", "position": [ {"x":126.9152195932067,"y":37.440055999842087}, {"x":129.081740279074182,"y":35.077713820938776} ], \'label\':"부산행", "labelColor":"#000000" }\r',
